"""Embedded default brain (DATA, not code copied from v1).

The Offline Brain rules live here as string constants so the BRAIN tab
is never empty and public builds can scan without any readable brain
file on disk. Source data: resources/brain_rules.yaml and brain.txt.
"""

DEFAULT_BRAIN_YAML = '# =============================================================================\n#  B-ROLL FINDER — OFFLINE BRAIN  (koi API key nahi chahiye)\n# =============================================================================\n#  Yeh file tool ka dimaagh hai. Is mein AI nahi, balki RULES hain:\n#   - script mein se moments, naam, saal aur events kaise pehchanne hain\n#   - YouTube par kya search karna hai\n#   - transcript mein kaunse alfaaz scandal, controversy, interview, news,\n#     emotional moment, waghera ki nishani hain, aur un ke kitne points hain\n#\n#  Kaise behtar karein:\n#   - Koi achhi clip miss ho rahi ho: us mein bola gaya khaas jumla\n#     neeche us category ki "phrases" list mein add kar dein.\n#   - Ghalat clips aa rahi hon: un ka jumla "penalties" mein daal dein.\n#   - Points (weight) barha kar kisi cheez ki ahmiyat barha sakte hain.\n#\n#  Lines jo "#" se shuru hoti hain, woh sirf notes hain.\n#  Spaces (indentation) ka khayal rakhein, YAML file mein yeh zaroori hain.\n# =============================================================================\n\nversion: 1\n\n# -----------------------------------------------------------------------------\n# PART A — SCRIPT SAMAJHNA\n# -----------------------------------------------------------------------------\nscript:\n  # Ek moment kitne jumlon ka ho sakta hai\n  max_sentences_per_moment: 2\n  # Script ke shuru ke jumle jo skip karne hain (salaam, intro, CTA)\n  skip_sentence_patterns:\n    - "^(hi|hey|hello|welcome)\\\\b"\n    - "\\\\b(subscribe|like this video|hit the bell|comment below|let\'?s get (into|started))\\\\b"\n    - "\\\\bin (this|today\'?s) video\\\\b"\n    - "\\\\bthanks for watching\\\\b"\n    - "^(have|did|do|would|could|will|are|were) you\\\\b"\n    - "\\\\b(what about you|let me know)\\\\b"\n\n  # Bare harfon wale yeh alfaaz naam nahi hote (jumle ke shuru mein aate hain)\n  not_names:\n    [The, A, An, In, On, At, But, And, Or, So, Then, When, After, Before, Years,\n     Later, Instead, This, That, These, Those, It, He, She, They, We, I, You,\n     His, Her, Their, Our, My, Your, Its, What, Why, How, Who, Where, Meanwhile,\n     However, Today, Now, Still, Even, Just, Only, Also, Because, Since, While,\n     During, Despite, Although, If, As, From, For, With, By, Of, To, One, Two,\n     January, February, March, April, May, June, July, August, September,\n     October, November, December, Monday, Tuesday, Wednesday, Thursday, Friday,\n     Saturday, Sunday, Like, Between, Read, Have, Has, Had, Did, Do, Does,\n     Never, Every, Each, Many, Most, Some, All, Here, There, Back, Not, No, Yes,\n     Let, Know, Keep, Think, Imagine, Remember, Picture, Look, Today\'s, Nobody,\n     Everyone, Someone, Something, Nothing, Almost, Finally, First, Last, Next]\n\n  # Event ke alfaaz: jis jumle mein yeh hon, us ko B-roll chahiye.\n  # ORDER ZAROORI HAI: upar wale groups ko pehle tarjeeh milti hai.\n  # "generic: true" wale groups (aam alfaaz) sirf tab use hote hain jab\n  # koi khaas event na mile, aur un ke alfaaz clip match mein nahi gine jate.\n  # Har group ke saath "show" likha hai ke kaisi footage chahiye,\n  # aur "query_words" jo YouTube search mein judte hain.\n  events:\n    award_show:\n      words: [vma, vmas, grammy, grammys, oscar, oscars, emmy, emmys, award, awards,\n              ceremony, red carpet, golden globes, bet awards, ama, amas, brit awards, met gala]\n      show: "live broadcast of the moment at the ceremony"\n      query_words: [live, stage]\n    legal:\n      words: [lawsuit, sued, sue, court, trial, judge, verdict, arrested, arrest, charged, charges,\n              police, jail, prison, settlement, testimony, testified, allegations, accused, investigation]\n      show: "news coverage, court footage or official statement"\n      query_words: [news, court]\n    scandal:\n      words: [scandal, leaked, leak, exposed, controversy, backlash, cancelled, canceled, apology,\n              apologized, apologise, accused, secret, hidden, cover-up, fraud]\n      show: "the exposed moment, news coverage and any apology"\n      query_words: [news, apology]\n    feud:\n      words: [feud, fight, beef, rivalry, clash, diss, called out, attacked, slammed, insulted,\n              interrupted, stormed, grabbed, drama, war]\n      show: "the confrontation itself and news coverage of it"\n      query_words: [moment, news]\n    relationship:\n      words: [dating, married, marriage, divorce, divorced, breakup, broke up, engaged, engagement,\n              split, relationship, boyfriend, girlfriend, wife, husband, wedding, cheating]\n      show: "public appearances together or interview about the relationship"\n      query_words: [interview, news]\n    business:\n      words: [masters, master recordings, bought back, bought, sold, record deal, deal, contract, rights, label, company, ownership, signed,\n              billion, million, sale, acquired, fired, quit, resigned]\n      show: "news report or interview explaining the deal"\n      query_words: [news, explained]\n    performance:\n      words: [concert, tour, performance, performed, stage, show, halftime, super bowl, festival, coachella]\n      show: "concert or stage footage"\n      query_words: [live, performance]\n    music_release:\n      words: [album, albums, song, songs, single, re-record, re-recorded, re-recording, recorded again, music video, released, release, studio]\n      show: "official music video, release coverage or interview about the album"\n      query_words: [interview, announcement]\n    career_moment:\n      generic: true\n      words: [won, win, record, history, first, biggest, comeback, retire, retired, debut, broke,\n              success, viral, famous, fame, number one]\n      show: "the milestone moment and reactions"\n      query_words: [moment, history]\n    speech:\n      generic: true\n      words: [said, speech, statement, announced, announcement, revealed, admitted, confessed,\n              told, responded, response, interview, press conference, podcast]\n      show: "the person speaking, from the original source"\n      query_words: [interview, full]\n\n  # YouTube search kaise banayein. {main} = script ka main insaan,\n  # {names} = is moment ke naam, {year} = saal, {event} = event ka lafz,\n  # {extra} = upar wale group ke query_words.\n  query_templates:\n    - "{main} {names} {event} {year} {extra}"\n    - "{main} {event} {year} interview"\n    - "{main} {names} {event} news"\n  max_query_words: 9\n  queries_per_moment: 2   # kam searches = YouTube block ka khatra kam\n\n# -----------------------------------------------------------------------------\n# PART B — TRANSCRIPT MEIN BEST CLIPS DHOONDNA\n# -----------------------------------------------------------------------------\nclips:\n  window_seconds: 30        # ek waqt mein transcript ka kitna hissa jaancha jaye\n  step_seconds: 10          # window kitna aage khiske\n  min_length: 8             # clip kam az kam kitne second ki ho\n  max_length: 40            # clip zyada se zyada kitne second ki ho\n  pre_roll: 2               # clip ahem lafz se kitna pehle shuru ho\n  min_gap_between_clips: 20 # ek hi video ki do clips mein kam az kam faasla\n  min_relevance: 3          # is se kam relevance wali clip reject (1-10)\n  require_name_or_year: true # clip mein script ka koi naam ya saal hona zaroori\n\n  # Relevance points: script ke alfaaz transcript mein milne par\n  relevance_points:\n    name: 3          # script ka naam (jaise Kanye West)\n    main_subject: 2  # script ka main insaan (jaise Taylor Swift)\n    year: 2          # saal (jaise 2009)\n    event_word: 2    # event ka lafz (jaise VMA, lawsuit)\n    other_keyword: 1 # baqi ahem alfaaz\n    title_match: 1   # video ke title mein moment ke alfaaz hon to har window ko bonus\n  relevance_per_point: 1.2   # har point se 1-10 score kitna barhe\n\n  interest_per_point: 1.0\n\n  # Categories: har category ke jumle aur un ke points.\n  # Jitne zyada points, utni dilchasp clip. Sab se zyada points wali\n  # category clip ki category banti hai.\n  categories:\n    Scandal:\n      weight: 3\n      phrases: [scandal, leaked, leak, exposed, allegations, accused, lawsuit, sued, arrested,\n                investigation, cover up, fraud, secret, caught, admitted, confessed, cheating,\n                court, charges, police, under fire, backlash]\n    Controversy:\n      weight: 3\n      phrases: [controversy, controversial, feud, beef, fight, attacked, slammed, criticized,\n                criticised, called out, outrage, booed, booing, interrupted, disrespect,\n                disrespectful, rude, angry, furious, shade, diss, war, drama, clash, insult,\n                "how dare", unacceptable, "not okay"]\n    Key Statement:\n      weight: 2\n      phrases: ["the truth is", "i want to be clear", "let me be clear", "i never", "i always",\n                "i decided", "i wanted", "i felt", "i was", "to be honest", honestly,\n                "the reason", "i realized", "i learned", "for the first time", "i\'m going to",\n                "i will", "i won\'t", "my side", "what happened was", "i\'m sorry", "i apologize"]\n    Emotional Moment:\n      weight: 2\n      phrases: ["[crying]", crying, cried, tears, heartbroken, devastated, "broke my heart",\n                emotional, "i\'m sorry", shocked, scared, hurt, painful, "so hard", "[laughter]",\n                laughing, "oh my god", "i can\'t believe", unbelievable]\n    News Report:\n      weight: 2\n      phrases: ["breaking news", "breaking", "we\'ve learned", "we have learned", "sources say",\n                "according to", "reports", "reported", "tonight", "this morning", "just in",\n                "officials", "statement", "confirmed", "the network", "correspondent",\n                "joining us", "live from", "developing story"]\n    Interview:\n      weight: 1.5\n      phrases: ["what was it like", "how did you feel", "how do you feel", "tell us", "tell me about",\n                "can you talk about", "what happened", "why did you", "do you think",\n                "when did you", "thank you for being here", "welcome to the show",\n                "great to have you", "sit down with"]\n    Reaction:\n      weight: 1.5\n      phrases: ["[applause]", applause, "[cheering]", cheering, "[booing]", "the crowd",\n                "the audience", gasps, "everyone was", "people were", reacted, reaction]\n    Performance:\n      weight: 1\n      phrases: ["[music]", "[singing]", performing, performance, "on stage", concert, tour,\n                "sing", "song"]\n\n  # Minus points: aisi jagahen jahan clip nahi chahiye\n  penalties:\n    phrases:\n      - { phrase: "subscribe", points: 4 }\n      - { phrase: "hit the bell", points: 4 }\n      - { phrase: "like and subscribe", points: 5 }\n      - { phrase: "sponsored by", points: 6 }\n      - { phrase: "this video is sponsored", points: 6 }\n      - { phrase: "use code", points: 5 }\n      - { phrase: "link in the description", points: 4 }\n      - { phrase: "patreon", points: 4 }\n      - { phrase: "welcome back to my channel", points: 4 }\n      - { phrase: "in today\'s video", points: 3 }\n      - { phrase: "thanks for watching", points: 4 }\n      - { phrase: "comment below", points: 3 }\n    intro_seconds: 15    # video ke pehle itne second\n    intro_penalty: 2\n    outro_seconds: 30    # video ke aakhri itne second\n    outro_penalty: 2\n\n# -----------------------------------------------------------------------------\n# VIDEO SOURCE — kaunsi video behtar hai\n# -----------------------------------------------------------------------------\nsources:\n  # In channels ki footage asal aur bharose wali hoti hai (interest +)\n  trusted_channels:\n    bonus: 1.5\n    names: [cnn, bbc, nbc, cbs, abc, fox, sky news, reuters, associated press, ap archive,\n            al jazeera, msnbc, cbc, guardian, nytimes, washington post, wsj,\n            mtv, e! news, entertainment tonight, access hollywood, extra, tmz, people,\n            billboard, rolling stone, vanity fair, vogue, gq, variety,\n            theellenshow, ellen, the tonight show, jimmy kimmel, late show, graham norton,\n            the view, good morning america, today, 60 minutes, howard stern, oprah,\n            vevo, " - topic", official]\n  # Title mein yeh alfaaz hon to video achhi hai\n  good_title_words:\n    bonus: 1\n    words: [official, full, live, interview, speech, footage, original, exclusive, uncut,\n            press conference, statement, news]\n  # Title mein yeh alfaaz hon to aksar commentary/fan video hoti hai\n  bad_title_words:\n    penalty: 2\n    words: [reaction, reacts, "top 10", "top 5", ranking, explained, compilation, edit,\n            fan made, fanmade, theory, theories, "ai ", parody, tiktok, shorts, meme, "#shorts"]\n\n# -----------------------------------------------------------------------------\n# MERI PASAND — apni channel ke hisaab se\n# -----------------------------------------------------------------------------\npreferences:\n  # In alfaaz wali clips ko extra points (apni pasand ke alfaaz daalein)\n  boost_phrases: []\n  # Yeh channels hamesha skip karein\n  blocked_channels: []\n  # Is se lambi videos skip (minutes)\n  max_video_minutes: 90\n'

DEFAULT_BRAIN_TXT = '############################################################################\n#  B-ROLL FINDER — BRAIN FILE\n#  Yeh file tool ka "dimaagh" hai. AI har dafa yahi rules parh kar kaam karega.\n#  Aap isay Notepad mein khol kar kabhi bhi badal sakte hain.\n#\n#  Lines jo "#" se shuru hoti hain, woh sirf aap ke liye notes hain.\n#  AI un ko ignore karega. Baqi sab AI ke liye rules hain (English mein,\n#  kyunke AI English rules sab se achhe samajhta hai).\n############################################################################\n\n\n=== WHO YOU ARE ===\nYou are an expert B-roll researcher for a YouTube documentary / commentary\nchannel. You think like a video editor: you want footage that makes viewers\nstop scrolling. You care about real moments, real reactions and real people,\nnot generic filler.\n\n\n############################################################################\n#  PART A — SCRIPT SAMAJHNA\n#  Yahan rules hain ke script ki kaunsi lines ko B-roll chahiye aur\n#  YouTube par kya search karna hai.\n############################################################################\n\n=== PART A: UNDERSTANDING THE SCRIPT ===\n\n1. Split the script into moments that need B-roll. A new moment starts when\n   the script mentions a new event, person, place, date, claim or emotion.\n\n2. Every one of these needs its own B-roll moment:\n   - A specific event (award show, concert, lawsuit, breakup, announcement)\n   - A specific person being named or quoted\n   - A claim, rumor or accusation\n   - A turning point ("everything changed when...", "then came...")\n   - A number or record ("sold 2 million copies", "the biggest tour ever")\n\n3. Skip lines that are pure narration with nothing to show, like greetings,\n   "let\'s get into it", or the channel\'s own call to action.\n\n4. For each moment, write YouTube searches that find REAL footage:\n   - Always use specific names, years, places and event names.\n   - BAD search:  "taylor swift drama"\n   - GOOD search: "taylor swift kanye west vma 2009 stage"\n   - Mix search styles per moment:\n       a) the event itself ("... live", "... full speech", "... red carpet")\n       b) news coverage ("... news report", "... breaking news")\n       c) interviews ("... interview", "... responds", "... talks about")\n       d) reaction / commentary ("... reaction", "... explained")\n\n5. Also list keywords likely to be SPOKEN in matching footage (names,\n   places, nicknames, song or album titles). These help find the right\n   videos faster.\n\n\n############################################################################\n#  PART B — BEST CLIPS CHUNNA\n#  Yahan rules hain ke video ki transcript mein se kaunsa hissa\n#  B-roll ke liye best hai.\n############################################################################\n\n=== PART B: PICKING THE BEST CLIPS ===\n\nWHAT MAKES A GREAT CLIP (highest priority first):\n  1. SCANDAL       – an accusation, leak, exposed secret, legal trouble\n  2. CONTROVERSY   – public fight, feud, backlash, heated disagreement\n  3. KEY STATEMENT – the person themselves saying something important,\n                     surprising or quotable about the topic\n  4. EMOTIONAL     – crying, anger, shock, laughing, a voice breaking\n  5. NEWS REPORT   – anchors announcing the event, breaking news segments\n  6. INTERVIEW     – a direct answer to a question about the topic\n  7. REACTION      – crowd, fans or other celebrities reacting live\n  8. PERFORMANCE   – stage, concert or show footage tied to the topic\n  9. BACKGROUND    – general footage of the person or place (lowest)\n\nGOOD CLIP RULES:\n  - It must clearly match the script line, not just the general subject.\n  - It should make sense on its own, without the rest of the video.\n  - Prefer the ORIGINAL source (official channel, news network, the event\n    itself) over someone re-uploading or talking over it.\n  - Prefer the person speaking for themselves over a narrator describing it.\n  - Ideal length: 5 to 30 seconds. Never longer than 45 seconds.\n  - Start the clip a moment BEFORE the key line, so it doesn\'t feel cut off.\n\nALWAYS IGNORE / REJECT:\n  - Video intros, outros, "like and subscribe", channel promos\n  - Sponsor segments and ads ("this video is sponsored by...")\n  - A YouTuber just reading a script with no real footage\n  - Clips where the topic is only mentioned in passing\n  - Fan edits, AI-generated or fake videos, obvious clickbait\n  - Anything that is speculation presented as fact, unless the script\n    itself is about that rumor\n\nSCORING (1 to 10):\n  - relevance: how exactly does it match the script line?\n      10 = this IS the moment the script describes\n       5 = same topic, but a different moment\n       1 = barely related\n  - interest: how much will viewers want to watch it?\n      10 = shocking, emotional, viral-worthy\n       5 = informative but calm\n       1 = boring or filler\n\n\n############################################################################\n#  EXAMPLES — AI in se seekhta hai ke aap ko kya pasand hai.\n#  Jab bhi tool koi achhi ya buri clip de, yahan ek example add kar dein.\n############################################################################\n\n=== EXAMPLES ===\n\nSCRIPT LINE: "In 2009, Kanye West stormed the VMA stage and took the mic\nfrom a 19-year-old Taylor Swift."\n  GOOD CLIP: The live VMA broadcast at the exact moment Kanye walks on stage\n    and takes the microphone, with the crowd booing.\n    -> category: Controversy | relevance 10 | interest 10\n  GOOD CLIP: A news anchor the next morning reporting on the incident.\n    -> category: News Report | relevance 9 | interest 7\n  BAD CLIP: A YouTuber\'s "Top 10 VMA moments" video talking over a still image.\n    -> reason: not original footage, just commentary\n\nSCRIPT LINE: "She fought for years to own her own music."\n  GOOD CLIP: Taylor Swift in an interview explaining in her own words why\n    owning her masters matters to her.\n    -> category: Key Statement | relevance 9 | interest 8\n  BAD CLIP: A music-business explainer video about record contracts in\n    general, with no mention of her.\n    -> reason: same topic, but not about her\n\n\n############################################################################\n#  MERI PASAND (MY PREFERENCES)\n#  Yeh hissa aap ka hai. Apni channel ke hisaab se badal dein.\n#  Example: "Prefer news channels like CNN, BBC" ya "Old footage pasand hai"\n############################################################################\n\n=== MY PREFERENCES ===\n- My channel style: documentary / storytelling about celebrities and news.\n- Prefer real footage over commentary videos.\n- Prefer clips where people speak English clearly.\n- Prefer high-view, well-known videos when two clips are equally good.\n# - Yahan apni aur pasand add karein, har line "-" se shuru karein.\n'
